const pool = new pg.Pool({ max: 5, idleTimeoutMillis: 30_000 });

async function campaign() {
  const { rows } = await pool.query(
    'SELECT pg_try_advisory_lock(42) AS ok');
  isLeader = rows[0].ok;
}

async function resign() {
  await pool.query('SELECT pg_advisory_unlock(42)');
  isLeader = false;
}

